def lbs(arr):
    n = len(arr)
    up = [1] * n
    down = [1] * n
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j]:
                up[i] = max(up[i], up[j] + 1)
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if arr[i] > arr[j]:
                down[i] = max(down[i], down[j] + 1)
    max_length = 0
    for i in range(n):
        max_length = max(max_length, up[i] + down[i] - 1)
    return max_length
